pub struct LspSession {
    pub process: Child,
    pub request_id: Mutex<u64>,
    pub pending_requests: Mutex<HashMap<u64, Sender<LspResponse>>>,
    pub diagnostics: Mutex<HashMap<String, Vec<lsp_types::Diagnostic>>>,
    pub capabilities: Mutex<Option<ServerCapabilities>>,
    tx: Mutex<Option<Sender<String>>>,
}

impl LspSession {
    pub fn new(server: &LspServer) -> std::io::Result<Self> {
        let mut cmd = std::process::Command::new(&server.cmd);
        cmd.args(&server.args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());

        let mut process = cmd.spawn()?;

        let stdin = process.stdin.take().unwrap();
        let stdout = process.stdout.take().unwrap();

        let (tx, rx): (Sender<String>, Receiver<String>) = channel();

        let writer = std::io::BufWriter::new(stdin);
        let mut writer = writer;

        thread::spawn(move || {
            for msg in rx {
                let _ = writer.write_all(msg.as_bytes());
                let _ = writer.flush();
            }
        });

        let reader = BufReader::new(stdout);
        let (diag_tx, _diag_rx): (Sender<LspResponse>, Receiver<LspResponse>) = channel();

        thread::spawn(move || {
            for line in reader.lines() {
                if let Ok(line) = line {
                    if let Some(msg) = parse_message(&line) {
                        match msg {
                            LspMessage::Notification { method, params } => {
                                if method == "textDocument/publishDiagnostics" {
                                    if let Ok(params) = serde_json::from_value::<
                                        lsp_types::PublishDiagnosticsParams,
                                    >(params)
                                    {
                                        let resp = LspResponse::Diagnostics(params);
                                        let _ = diag_tx.send(resp);
                                    }
                                }
                            }
                            LspMessage::Response { id, result } => {
                                if let Some(id) = id {
                                    let resp = LspResponse::Response(id, result);
                                    let _ = diag_tx.send(resp);
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
        });

        let (tx2, rx2) = channel::<String>();

        thread::spawn(move || {
            for msg in rx2 {
                if let Ok(msg) = serde_json::to_string(&msg) {
                    let _ = tx.send(msg);
                }
            }
        });

        Ok(Self {
            process,
            request_id: Mutex::new(0),
            pending_requests: Mutex::new(HashMap::new()),
            diagnostics: Mutex::new(HashMap::new()),
            capabilities: Mutex::new(None),
            tx: Mutex::new(Some(tx2)),
        })
    }

    pub fn initialize(&self, uri: &str) -> std::result::Result<ServerCapabilities, String> {
        let id = self.next_id();

        let params = lsp_types::InitializeParams::default();

        let request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": id,
            "method": "initialize",
            "params": params
        });

        self.send_request(request);

        let (tx, rx) = channel();
        self.pending_requests.lock().insert(id, tx);

        let response = rx
            .recv_timeout(Duration::from_secs(10))
            .map_err(|e| format!("Timeout waiting for initialize: {}", e))?;

        match response {
            LspResponse::Response(_, result) => {
                let caps: lsp_types::InitializeResult =
                    serde_json::from_value(result.unwrap_or_default())
                        .map_err(|e| format!("Failed to parse capabilities: {}", e))?;
                let caps_clone = caps.capabilities.clone();
                *self.capabilities.lock() = Some(caps_clone);
                Ok(caps.capabilities)
            }
            _ => Err("Invalid response".to_string()),
        }
    }

    pub fn open_document(
        &self,
        uri: &str,
        text: &str,
        language_id: &str,
    ) -> std::result::Result<(), String> {
        let params = serde_json::json!({
            "textDocument": {
                "uri": uri,
                "text": text,
                "version": 0,
                "languageId": language_id
            }
        });

        let notification = serde_json::json!({
            "jsonrpc": "2.0",
            "method": "textDocument/didOpen",
            "params": params
        });

        self.send_notification(notification);
        Ok(())
    }

    pub fn change_document(
        &self,
        uri: &str,
        version: i32,
        text: &str,
    ) -> std::result::Result<(), String> {
        let params = serde_json::json!({
            "textDocument": {
                "uri": uri,
                "version": version
            },
            "contentChanges": [{
                "text": text
            }]
        });

        let notification = serde_json::json!({
            "jsonrpc": "2.0",
            "method": "textDocument/didChange",
            "params": params
        });

        self.send_notification(notification);
        Ok(())
    }

    pub fn save_document(&self, uri: &str) -> std::result::Result<(), String> {
        let params = serde_json::json!({
            "textDocument": {
                "uri": uri
            }
        });

        let notification = serde_json::json!({
            "jsonrpc": "2.0",
            "method": "textDocument/didSave",
            "params": params
        });

        self.send_notification(notification);
        Ok(())
    }

    pub fn close_document(&self, uri: &str) -> std::result::Result<(), String> {
        let params = serde_json::json!({
            "textDocument": {
                "uri": uri
            }
        });

        let notification = serde_json::json!({
            "jsonrpc": "2.0",
            "method": "textDocument/didClose",
            "params": params
        });

        self.send_notification(notification);
        Ok(())
    }

    pub fn request_completion(
        &self,
        uri: &str,
        position: Position,
    ) -> std::result::Result<Vec<CompletionItem>, String> {
        let id = self.next_id();

        let params = serde_json::json!({
            "textDocumentPosition": {
                "textDocument": { "uri": uri },
                "position": position
            }
        });

        let request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": id,
            "method": "textDocument/completion",
            "params": params
        });

        self.send_request(request);

        let (tx, rx) = channel();
        self.pending_requests.lock().insert(id, tx);

        match rx.recv_timeout(Duration::from_secs(5)) {
            Ok(LspResponse::Response(_, result)) => {
                let response: Option<lsp_types::CompletionResponse> =
                    serde_json::from_value(result.unwrap_or_default())
                        .map_err(|e| format!("Failed to parse completions: {}", e))?;

                match response {
                    Some(lsp_types::CompletionResponse::Array(items)) => Ok(items),
                    Some(lsp_types::CompletionResponse::List(list)) => Ok(list.items),
                    None => Ok(vec![]),
                }
            }
            _ => Ok(vec![]),
        }
    }

    pub fn request_formatting(&self, uri: &str) -> std::result::Result<Vec<TextEdit>, String> {
        let id = self.next_id();

        let params = serde_json::json!({
            "textDocument": { "uri": uri },
            "options": {
                "tabSize": 4,
                "insertSpaces": true
            }
        });

        let request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": id,
            "method": "textDocument/formatting",
            "params": params
        });

        self.send_request(request);

        let (tx, rx) = channel();
        self.pending_requests.lock().insert(id, tx);

        match rx.recv_timeout(Duration::from_secs(5)) {
            Ok(LspResponse::Response(_, result)) => {
                let edits: Option<Vec<TextEdit>> =
                    serde_json::from_value(result.unwrap_or_default())
                        .map_err(|e| format!("Failed to parse formatting response: {}", e))?;
                Ok(edits.unwrap_or_default())
            }
            _ => Ok(vec![]),
        }
    }

    pub fn request_range_formatting(
        &self,
        uri: &str,
        range: Range,
    ) -> std::result::Result<Vec<TextEdit>, String> {
        let id = self.next_id();

        let params = serde_json::json!({
            "textDocument": { "uri": uri },
            "range": range,
            "options": {
                "tabSize": 4,
                "insertSpaces": true
            }
        });

        let request = serde_json::json!({
            "jsonrpc": "2.0",
            "id": id,
            "method": "textDocument/rangeFormatting",
            "params": params
        });

        self.send_request(request);

        let (tx, rx) = channel();
        self.pending_requests.lock().insert(id, tx);

        match rx.recv_timeout(Duration::from_secs(5)) {
            Ok(LspResponse::Response(_, result)) => {
                let edits: Option<Vec<TextEdit>> =
                    serde_json::from_value(result.unwrap_or_default())
                        .map_err(|e| format!("Failed to parse range formatting response: {}", e))?;
                Ok(edits.unwrap_or_default())
            }
            _ => Ok(vec![]),
        }
    }

    pub fn get_diagnostics(&self, uri: &str) -> Vec<lsp_types::Diagnostic> {
        self.diagnostics
            .lock()
            .get(uri)
            .cloned()
            .unwrap_or_default()
    }

    pub fn has_completion(&self) -> bool {
        let caps = self.capabilities.lock();
        if let Some(caps) = caps.as_ref() {
            caps.completion_provider.is_some()
        } else {
            false
        }
    }

    pub fn has_formatting(&self) -> bool {
        let caps = self.capabilities.lock();
        if let Some(caps) = caps.as_ref() {
            caps.document_formatting_provider.is_some()
        } else {
            false
        }
    }

    fn next_id(&self) -> u64 {
        let mut id = self.request_id.lock();
        *id += 1;
        *id
    }

    fn send_request(&self, request: serde_json::Value) {
        if let Some(tx) = self.tx.lock().as_ref() {
            let _ = tx.send(request.to_string());
        }
    }

    fn send_notification(&self, notification: serde_json::Value) {
        if let Some(tx) = self.tx.lock().as_ref() {
            let _ = tx.send(notification.to_string());
        }
    }
}

impl Drop for LspSession {
    fn drop(&mut self) {
        let _ = self.process.kill();
    }
}

enum LspMessage {
    Request {
        id: Option<u64>,
        method: String,
        params: serde_json::Value,
    },
    Response {
        id: Option<u64>,
        result: Option<serde_json::Value>,
    },
    Notification {
        method: String,
        params: serde_json::Value,
    },
}

fn parse_message(line: &str) -> Option<LspMessage> {
    if let Ok(msg) = serde_json::from_str::<serde_json::Value>(line) {
        if msg.get("jsonrpc").and_then(|v| v.as_str()) == Some("2.0") {
            if let Some(id) = msg.get("id") {
                if let Some(result) = msg.get("result") {
                    return Some(LspMessage::Response {
                        id: id.as_u64(),
                        result: Some(result.clone()),
                    });
                }
            }
            if let Some(method) = msg.get("method").and_then(|v| v.as_str()) {
                return Some(LspMessage::Notification {
                    method: method.to_string(),
                    params: msg
                        .get("params")
                        .cloned()
                        .unwrap_or(serde_json::Value::Null),
                });
            }
        }
    }
    None
}

enum LspResponse {
    Response(u64, Option<serde_json::Value>),
    Diagnostics(lsp_types::PublishDiagnosticsParams),
}

pub fn lsp_position_to_offset(content: &str, position: Position) -> usize {
    let mut offset = 0;
    for (line_num, line) in content.lines().enumerate() {
        if line_num == position.line as usize {
            for (char_num, _) in line.char_indices() {
                if char_num >= position.character as usize {
                    break;
                }
                offset += 1;
            }
            break;
        }
        offset += line.len() + 1;
    }
    offset
}

pub fn offset_to_lsp_position(content: &str, offset: usize) -> Position {
    let mut line = 0;
    let mut column = 0;
    let mut current_offset = 0;

    for ch in content.chars() {
        if current_offset >= offset {
            break;
        }
        if ch == '\n' {
            line += 1;
            column = 0;
        } else {
            column += 1;
        }
        current_offset += 1;
    }

    Position {
        line: line as u32,
        character: column as u32,
    }
}

pub fn range_to_lsp_range(content: &str, start: usize, end: usize) -> Range {
    Range {
        start: offset_to_lsp_position(content, start),
        end: offset_to_lsp_position(content, end),
    }
}

